<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\Database\Connection;use MarketForecast\Database\Migrator;use MarketForecast\Forecast\{ForecastOrchestrator,QuantForecastEngine,ForecastFreezer};use MarketForecast\Jobs\JobLock;use PHPUnit\Framework\TestCase;
final class ForecastOrchestratorTest extends TestCase { public function testRunIsIdempotentAndStateful():void{$p=tempnam(sys_get_temp_dir(),'orch-');$pdo=Connection::open($p);(new Migrator($pdo))->apply(dirname(__DIR__).'/database/migrations','2026-01-01T00:00:00Z');$pdo->exec("INSERT INTO experiments(experiment_code,name,description,start_at,status,config_json) VALUES('EXP-001','Test','Test','2026-01-01T00:00:00Z','ACTIVE','{}')");$o=new ForecastOrchestrator($pdo,new JobLock($pdo),new QuantForecastEngine(),new ForecastFreezer());$id=$o->start(1,'forecast:EXP-001:2026-01-01','2026-01-01T00:00:00Z','2026-01-01T00:00:00Z');self::assertNotNull($id);self::assertNull($o->start(1,'forecast:EXP-001:2026-01-01','2026-01-01T00:00:00Z','2026-01-01T00:00:00Z'));$o->markState($id,'MARKET_DATA_READY','2026-01-01T00:01:00Z');self::assertSame('MARKET_DATA_READY',$pdo->query('SELECT state_detail FROM forecast_runs')->fetchColumn());@unlink($p);@unlink($p.'-wal');@unlink($p.'-shm');} }
